--Thanks to Jip who provided the below code as part of the FAF changes to how brains are handled
local StandardBrain = import("/lua/aibrain.lua").AIBrain
local AiBotEvents = import('/lua/AiBot/AI/AiBotEvents.lua')

NewAIBrain = Class(StandardBrain) {

    OnBeginSession = function(self)
        StandardBrain.OnBeginSession(self)
        import('/lua/AiBot/AI/AiBotOverseer.lua').bBeginSessionTriggered = true
    end,

    OnDefeat = function(self)
        StandardBrain.OnDefeat(self)
        ForkThread(AiBotEvents.OnPlayerDefeated, self)

    end,

    OnCreateAI = function(self, planName)
        StandardBrain.OnCreateAI(self)
        --LOG('AiBotAI brain class OnCreateAI triggered, brain nickname='..self.Nickname)
        self.AiBotAI = true
        import('/lua/AiBot/AI/AiBotUtilities.lua').bAiBotAIInGame = true
        ForkThread(AiBotEvents.OnCreateBrain, self, planName, false)
    end,

    OnCreateHuman = function(self, planName) --This doenst actually trigger; instead need a hook of simInit.lua
        StandardBrain.OnCreateHuman(self, planName)
        ForkThread(AiBotEvents.OnCreateBrain, self, planName, true)
    end,

}